#include <iostream>
#include <string>
#include <iomanip>
#include <algorithm>

using namespace std;

/**
 * GPE 10471: COUNTING CHAOS
 * 題目要求給定一個時間 HH:MM，找出下一個「回文時間」。
 * 判定規則：忽略 HH 的前導零；若 HH 為 0，則再忽略 MM 的前導零。
 * 例如 05:05 視為 505（是回文）；00:07 視為 7（是回文）。
 */

// 檢查數字字串是否為回文
bool isPalindrome(int h, int m) {
    string s = "";
    if (h > 0) {
        s += to_string(h);
        if (m < 10) s += "0"; // MM 必須保留兩位，因為 HH > 0 時 MM 也要被考慮進去
        s += to_string(m);
    } else {
        // 若 HH 為 0，僅考慮 MM
        s = to_string(m);
    }

    string rev = s;
    reverse(rev.begin(), rev.end());
    return s == rev;
}

int main() {
    int n;
    cin >> n;
    while (n--) {
        string time;
        cin >> time;
        int h = stoi(time.substr(0, 2));
        int m = stoi(time.substr(3, 2));

        while (true) {
            // 前進一分鐘
            m++;
            if (m == 60) {
                m = 0;
                h++;
            }
            if (h == 24) {
                h = 0;
            }

            if (isPalindrome(h, m)) {
                cout << setfill('0') << setw(2) << h << ":" << setw(2) << m << endl;
                break;
            }
        }
    }
    return 0;
}
